const T = {
  title: '解一元一次方程',
  original: '7x+-3=1x+4',
  step1: '第一步 · 移项',
  eq1: '7x-1x=4+3',
  step2: '第二步 · 合并同类项',
  eq2: '6x=7',
  step3: '第三步 · 系数化为 1',
  eq3: 'x=7/6'
};
const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: T.title },
      { kind: 'text', payload: T.original },
      { kind: 'text', payload: T.step1 },
      { kind: 'text', payload: T.eq1 },
      { kind: 'text', payload: T.step2 },
      { kind: 'text', payload: T.eq2 },
      { kind: 'text', payload: T.step3 },
      { kind: 'text', payload: T.eq3 }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(20, Math.min(W, H) * 0.045);
    var cardW = Math.min(W - 2 * margin, 780);
    var cardX = (W - cardW) / 2;
    var cardH = Math.max(96, Math.min(128, H * 0.19));
    var gap = Math.max(18, Math.min(34, H * 0.035));
    var startY = H * 0.28;
    var titleSize = Math.max(24, Math.min(34, W * 0.04));
    var originalSize = Math.max(22, Math.min(30, W * 0.034));
    var stepSize = Math.max(16, Math.min(20, W * 0.022));
    var eqSize = Math.max(22, Math.min(28, W * 0.032));

    function rectCommands(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }

    var paths = [];
    var children = [];
    var cardYs = [startY, startY + cardH + gap, startY + 2 * (cardH + gap)];

    for (var i = 0; i < 3; i++) {
      paths.push({ id: 'card' + (i + 1), commands: rectCommands(cardX, cardYs[i], cardW, cardH) });
      children.push({ type: 'path', pathId: 'card' + (i + 1), fill: '#f7fbff', stroke: '#2f5d8a' });
    }

    for (var j = 0; j < 2; j++) {
      var y1 = cardYs[j] + cardH + 4;
      var y2 = cardYs[j + 1] - 4;
      paths.push({ id: 'arrow' + (j + 1), commands: visualSdk.arrow(W / 2, y1, W / 2, y2) });
      children.push({ type: 'path', pathId: 'arrow' + (j + 1), fill: '#2f5d8a', stroke: '#2f5d8a' });
    }

    children.push({
      type: 'label', x: W / 2, y: H * 0.12, text: T.title,
      fontSize: titleSize, fontWeight: 'bold', fill: '#12263f', textAnchor: 'middle'
    });
    children.push({
      type: 'label', x: W / 2, y: H * 0.20, text: T.original,
      fontSize: originalSize, fontWeight: '600', fill: '#1f4e79', textAnchor: 'middle'
    });

    var steps = [
      { label: T.step1, eq: T.eq1 },
      { label: T.step2, eq: T.eq2 },
      { label: T.step3, eq: T.eq3 }
    ];
    for (var k = 0; k < steps.length; k++) {
      var cy = cardYs[k];
      children.push({
        type: 'label', x: cardX + 28, y: cy + 34,
        text: steps[k].label, fontSize: stepSize, fontWeight: 'bold',
        fill: '#1f4e79', textAnchor: 'start'
      });
      children.push({
        type: 'label', x: cardX + cardW / 2, y: cy + cardH * 0.68,
        text: steps[k].eq, fontSize: eqSize, fontWeight: '600',
        fill: '#111827', textAnchor: 'middle'
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
